steps.script:
GameState.state["factions"]["1"]["detachment"] = "Honoured Companions"
GameState.state.players["1"]["cp"] = 0
GameState.state.players["2"]["cp"] = 0
SettingsService.set("auto_allocate_wounds", true)
var xs := [1430.0, 1503.0, 1576.0]
var ms = GameState.state.units["U_CUSTODIAN_GUARD_B"].models
for i in range(ms.size()):
	ms[i]["position"] = {"x": xs[i % 3], "y": 1440.0}
tree.current_scene._recreate_unit_visuals()
var D = load("res://scripts/codex/custodes/CustodesDetachments.gd")
var ok: bool = D.within_objective_range(GameState.state.units["U_CUSTODIAN_GUARD_B"]) and not RulesEngine.is_unit_engaged("U_CUSTODIAN_GUARD_B", GameState.state)
PhaseManager.transition_to_phase(8)
return ok

var ph = PhaseManager.get_current_phase_instance()
var n := 0
for d in ph.dice_log:
	if str(d.get("context", "")) == "to_wound":
		for e in d.get("modifier_ledger", []):
			if str(e.get("source", "")).begins_with("Companion's Watch"):
				print("[cus11e honoured] ", e)
				n += 1
return n

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true
